package com.orbitcrm.shared.service;

import java.io.InputStream;

/**
 * Binary object storage abstraction for attachments and uploaded import files.
 *
 * <p>Purpose: decouple file handling from where files are stored (PRD section 39: large files do not belong in
 * PostgreSQL). Keys are always generated by the platform, never taken from user input, and start with
 * {@code tenants/<tenantId>/}. Implementations: local disk ({@code LocalStorageService}) and any S3-compatible
 * store (configured in {@code StorageConfig}).
 *
 * @author Abhay
 */
public interface StorageService {

    void put(String key, InputStream content, long size, String contentType);

    InputStream get(String key);

    void delete(String key);
}
